#!/usr/bin/env node
/* Generates precache-manifest.js (list of every app file + a content hash used as the cache version).
 * Run it before every deploy:   node tools/gen-precache.js
 * The service worker imports the generated file, so a changed file => new hash => clients refresh their cache. */
'use strict';
const fs = require('fs'), path = require('path'), crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..');
const SKIP_DIRS = new Set(['tools', 'tests', 'node_modules', '.git', 'licenses']);
const SKIP_FILES = new Set(['precache-manifest.js', 'README.md', 'package.json', 'package-lock.json']);
const SKIP_EXT = new Set(['.map', '.md', '.py', '.zip', '.7z']);

function walk(dir, out) {
  for (const name of fs.readdirSync(dir).sort()) {
    const full = path.join(dir, name), st = fs.statSync(full);
    if (st.isDirectory()) { if (!SKIP_DIRS.has(name)) walk(full, out); continue; }
    if (SKIP_FILES.has(name) || SKIP_EXT.has(path.extname(name))) continue;
    out.push(path.relative(ROOT, full).split(path.sep).join('/'));
  }
  return out;
}

const files = walk(ROOT, []);
const hash = crypto.createHash('sha256');
files.forEach(f => { hash.update(f); hash.update(fs.readFileSync(path.join(ROOT, f))); });
const version = hash.digest('hex').slice(0, 12);

const urls = ['./'].concat(files.map(f => './' + f));
const body = '/* AUTO-GENERATED by tools/gen-precache.js — do not edit. */\n' +
  'self.PRECACHE_VERSION = ' + JSON.stringify(version) + ';\n' +
  'self.PRECACHE_URLS = ' + JSON.stringify(urls, null, 1) + ';\n';
fs.writeFileSync(path.join(ROOT, 'precache-manifest.js'), body);
console.log('precache-manifest.js: ' + urls.length + ' URLs, version ' + version);
